.logo {
font-family: 'Lilita One';
font-size: 3em; /* Adjust size as needed */
font-weight: bold;
text-transform: uppercase;
display: flex;
}

.logo .first-word {
background-color: #000000; /* Black background */
color: #ffffff; /* White text */
padding: 10px 15px;
display: inline-block;
}

.logo .remaining-words {
border: 2px solid #000000;
background-color: #ffffff; /* White background */
color: #000000; /* Black text */
padding: 10px 15px;
display: inline-block;
margin-left: 5px;
}

/* Category Bar */
.category-bar {
background-color: #ffffff; /* White background */
border-bottom: 5px solid #000000; /* Black border below the category bar */
padding: 10px 20px;
text-align: center;
text-transform: uppercase; /* Convert text to uppercase */
font-size: 22px; /* Slightly larger font size */
font-weight: bold; /* Make it bold for emphasis */
}

.category-bar a {
color: #000000; /* Black text */
margin: 0 10px;
text-decoration: none;
font-size: 30pt; /* Inherit the font size from the category bar */
}

/* Main Content */
.main-content {
width: 60%;
font-size: 12pt;
margin: 20px auto;
text-align: left;
border-bottom: 5px solid #000000; /* Black border below main content */
padding-bottom: 20px;
}

.main-content h1 {
font-size: 44px;
font-weight: bold;
text-transform: uppercase;
margin-bottom: 10px;
}

.meta-info {
font-size: 12px;
color: #666666;
margin-bottom: 20px;
}

.main-content img.main-image {
width: 80%;
margin: 20px 0;
justify-content: center;
}

.article-text {
font-size: 20px;
line-height: 1.5;
text-align: justify;
}

/* Sidebar Styles */
.sidebar {
display: none; /* Make the sidebar invisible */
}

.related-articles {
display: none; /* Make the related articles invisible */
}

/* Footer Styles */
footer {
background-color: #ffffff; /* White background */
color: #000000; /* Black text */
text-align: center;
padding: 10px 0;
