.top-ad img {
width: 100%;
max-width: 728px;
height: auto;
}

/* General Reset */
* {
box-sizing: border-box;
margin: 0;
padding: 0;
}

/* General Styles */
body {
font-family: Arial, sans-serif;
background-color: #f5f5f5;
display: flex;
flex-direction: column;
align-items: center;
}

/* Container for Fixed-Width Content */
.container {
display: flex;
width: 1400px; /* Matches header width */
background-color: #ffffff;
padding: 20px; /* Add padding for spacing */
box-shadow: 0px 0px 10px rgba(0, 0, 0, 0.1);
overflow: hidden; /* Prevent content spillage */
}

/* Left and Right Borders */
body::before,
body::after {
content: \"\";
flex-grow: 1;
background-color: #e0e0e0;
}

body {
display: flex;
}

/* Header */
header {
width: 1400px; /* Matches container width */
background-color: #ffffff;
padding: 30px 30px;
display: flex;
justify-content: space-between;
align-items: center;
border-bottom: 2px solid #ddd;
}

/* Adjust Margins and Box-Sizing */
header, .container {
margin: 0 auto; /* Center content */
}

header::after {
content: \"\"; /* Image placeholder */
width: 750px; /* Set image width */
height: 100px; /* Set image height */
background-image: url('social_media_bars/express-social.png'); /* Replace with your image URL */
background-size: contain; /* Scale the image while maintaining aspect ratio */
background-repeat: no-repeat;
background-position: center;
margin-left: 10px; /* Add space between logo and image */
}

/* Logo Styling */
.logo-container {
display: flex;
align-items: center;
}

.logo {
font-family: Georgia, serif;
font-size: 80px; /* Increased font size */
font-weight: bold;
text-transform: uppercase;
}

/* Social Media Widget */
.social-media-widget img {
height: 45px;
}

/* Category Navigation Bar */
.category-bar {
width: 1400px; /* Matches header and container */
background-color: #ffffff;
text-align: center;
padding: 12px 0;
border-bottom: 2px solid #ddd;
}

.category-bar a {
text-decoration: none;
color: black;
font-family: Georgia, serif; /* Same as logo */
font-size: 16px;
font-weight: bold;
text-transform: uppercase;
margin: 0 20px;
}

.category-bar a:hover {
color: red;
}

/* Main Content Area */
.main-content {
width: 65%; /* Allocates 65% of container width */
padding: 20px; /* Add spacing within content */
}

.main-content h1 {
font-family: Georgia, serif;
font-size: 40px;
font-weight: bold;
margin-bottom: 10px;
}

.meta-info {
font-size: 14px;
color: gray;
margin-bottom: 10px;
}

.main-image {
width: 100%;
max-width: 100%; /* Ensure image doesn't exceed container width */
margin-bottom: 20px;
}

.article-text {
font-size: 16px;
line-height: 1.6;
}

/* Related Articles Section */

/* Sidebar Styles */
.sidebar {
display: none; /* Make the sidebar invisible */
}
.related-articles {
width: 30%; /* Allocates 30% of container width */
padding: 20px; /* Add spacing */
border-left: 2px solid #ddd; /* Separator for clarity */
}

.related-articles h2 {
color: red;
font-size: 20px;
margin-bottom: 10px;
}

.related-article {
margin-bottom: 10px;
}

.related-headline {
font-size: 14px;
text-decoration: none;
color: black;
}

.related-headline:hover {
color: red;
}

.related-image {
width: 100%;
max-width: 100%; /* Prevent image from spilling */
height: auto;
margin-bottom: 5px;
}

/* Footer */
footer {
width: 1400px; /* Matches container width */
background-color: #333;
color: white;
text-align: center;
text-transform: uppercase;
padding: 15px 0;
margin-top: 20px;
}
